// Tag staging responses with the environment name and alert on server errors.
const env = $argument

if ($response.status >= 500) {
  $notification.post("Staging error", String($response.status), $request.url)
}

if (!String($response.body).startsWith("{")) throw new Error("not a JSON object")
const body = JSON.parse($response.body)
body.env = env
console.log("tagged", $response.status, $response.body.length, "bytes")

$done({
  headers: Object.assign({}, $response.headers, { "X-Env": env }),
  body: JSON.stringify(body),
})
